 348 | async function launchChromeIfNeeded() {
 349 |   const providerStartUrl = resolveBrowserStartUrl();
 350 |   const alreadyRunning = await isPortInUse(CDP_PORT);
 351 |   if (alreadyRunning) {
 352 |     const reusable = ensureReusableChromeForProvider();
 353 |     if (!reusable.ok) {
