 358 |       const ready = await waitForCdpReady(CDP_PORT, 3000);
 359 |       if (!ready.ok) {
 360 |         console.warn(`[Launcher] CDP on :${CDP_PORT} not healthy: ${ready.error}. Re-launching.`);
 361 |       } else {
 362 |         await ensureManagedProviderTab(providerStartUrl);
 363 |         return true;
 364 |       }
 365 |     }
 366 |   }
 367 | 
 368 |   // Before launching a new managed Chrome, clean orphan processes and
 369 |   // stale lock files from the managed profile directory. An orphan instance
 370 |   // holding the profile lock prevents a new Chrome from binding to the
 371 |   // requested CDP port because Chrome forwards URL arguments to the
 372 |   // existing process instead of starting fresh with the new debug flags.
 373 |   cleanOrphanChromeProcesses();
