 375 |   const chromePath = findChromeBin();
 376 |   if (!chromePath) {
 377 |     console.warn(`[Launcher] Chrome not found. Start Chrome manually with --remote-debugging-port=${CDP_PORT}`);
 378 |     return false;
 379 |   }
 380 | 
 381 |   ensureDir(CHROME_USER_DATA);
 382 |   const uiPort = getAgentPort(PROJECT_CONFIG);
 383 |   const uiUrl = `http://${LOOPBACK_HOST}:${uiPort}`;
 384 |   const urls = process.env.ELECTRON_WRAPPER === '1'
