 386 |     : [uiUrl, providerStartUrl];
 387 |   try {
 388 |     const child = spawn(chromePath, [
 389 |       `--remote-debugging-port=${CDP_PORT}`,
 390 |       `--user-data-dir=${CHROME_USER_DATA}`,
 391 |       '--no-first-run',
 392 |       '--no-default-browser-check',
 393 |       '--window-size=1280,720',
 394 |       ...urls,
 395 |     ], { detached: true, stdio: 'ignore', windowsHide: true });
 396 |     child.unref();
 397 |     chromeChildProcess = child;
 398 |     console.log(`[Launcher] Chrome launched with CDP on :${CDP_PORT} (PID: ${child.pid})`);
 399 |     console.log(`[Launcher] UI opening at ${uiUrl} and ${providerStartUrl}`);
 400 | 
 401 |     // Wait for CDP readiness with explicit polling of /json/version.
 402 |     // A TCP listener alone is not CDP readiness. Readiness requires
 403 |     // a valid /json/version response with webSocketDebuggerUrl.
 404 |     const ready = await waitForCdpReady(CDP_PORT, 10000);
 405 |     if (!ready.ok) {
 406 |       console.warn(`[Launcher] CDP readiness check failed: ${ready.error}`);
 407 |       try { process.kill(child.pid, 'SIGTERM'); } catch { /* ignore */ }
 408 |       chromeChildProcess = null;
 409 |       console.warn('[Launcher] Chrome launched but CDP port never became ready. Startup will continue without managed Chrome.');
 410 |       return false;
 411 |     }
 412 | 
 413 |     console.log(`[Launcher] CDP ready on :${CDP_PORT} (${ready.browser})`);
 414 |     await ensureManagedProviderTab(providerStartUrl);
 415 |     return true;
 416 |   } catch (err) {
 417 |     console.warn(`[Launcher] Chrome launch failed but backend startup will continue: ${err.message}`);
 418 |     return false;
 419 |   }
