 430 | function describeAgentState(state) {
 431 |   const value = String(state || 'UNKNOWN').trim().toUpperCase();
 432 |   if (value === 'RUNNING') return 'thinking locally';
 433 |   if (value === 'WAITING') return 'waiting for the next browser instruction';
 434 |   if (value === 'DELIVERING') return 'writing evidence back to the browser';
 435 |   if (value === 'RECOVERING_BROWSER') return 'recovering the browser connection';
 436 |   if (value === 'FAILED') return 'broken';
 437 |   if (value === 'STOPPED') return 'stopped';
 438 |   if (value === 'IDLE') return 'idle';
 439 |   if (value === 'PROTOCOL_ERROR') return 'protocol error';
 440 |   return value.toLowerCase().replace(/_/g, ' ');
 441 | }
