 451 | async function ensureManagedProviderTab(providerUrl) {
 452 |   const cdp = getCdpHandler();
 453 |   const desiredUrl = isSupportedProviderStartUrl(providerUrl) ? providerUrl : DEFAULT_BROWSER_START_URL;
 454 |   try {
 455 |     await cdp.ensureConnection();
 456 |     const listed = await cdp.listTargets();
 457 |     const existing = Array.isArray(listed?.targets)
 458 |       ? listed.targets.find(target => isSupportedProviderPageTarget(target, desiredUrl))
 459 |       : null;
 460 |     if (existing) {
 461 |       return { ok: true, existing: true, targetId: existing.id, url: existing.url };
 462 |     }
 463 | 
 464 |     const created = await cdp.newTarget({ url: desiredUrl });
 465 |     console.log(`[Launcher] Opened managed provider tab at ${desiredUrl} (target: ${created.id})`);
 466 |     return { ok: true, existing: false, targetId: created.id, url: desiredUrl };
 467 |   } catch (error) {
 468 |     console.warn(`[Launcher] Failed to ensure managed provider tab: ${error.message}`);
 469 |     return { ok: false, error: error.message, url: desiredUrl };
 470 |   }
 471 | }
