 473 | function resolveBrowserStartUrl() {
 474 |   try {
 475 |     const configured = llmSettingsStore.load()?.browserStartUrl;
 476 |     if (isSupportedProviderStartUrl(configured)) return configured;
 477 |   } catch {}
 478 |   return DEFAULT_BROWSER_START_URL;
 479 | }
