 481 | function isSupportedProviderStartUrl(value) {
 482 |   return isSupportedProviderUrl(value);
 483 | }
 484 | 
 485 | function providerHostForUrl(value) {
 486 |   return providerIdFromUrl(value);
 487 | }
 488 | 
 489 | function isSupportedProviderPageTarget(target, desiredUrl) {
 490 |   if (!target || target.type !== 'page') return false;
 491 |   if (!isSupportedProviderStartUrl(target.url)) return false;
 492 |   return providerHostForUrl(target.url) === providerHostForUrl(desiredUrl);
 493 | }
