 495 | function ensureReusableChromeForProvider() {
 496 |   if (process.platform !== 'win32') {
 497 |     return { ok: true };
 498 |   }
 499 | 
 500 |   const listeners = findListeningProcessIdsForPort(CDP_PORT);
 501 |   if (!listeners.length) {
 502 |     return { ok: false, error: `CDP port ${CDP_PORT} is marked in use but no listening process could be resolved.` };
 503 |   }
 504 | 
 505 |   const headlessManaged = listeners.find(pid => {
 506 |     const commandLine = readWindowsProcessCommandLine(pid);
 507 |     return isHeadlessManagedChromeCommandLine(commandLine);
 508 |   });
 509 | 
 510 |   if (!headlessManaged) {
 511 |     return { ok: true };
 512 |   }
 513 | 
 514 |   try {
 515 |     execSync(`taskkill /pid ${headlessManaged} /t /f`, { stdio: 'ignore', windowsHide: true, timeout: 5000 });
 516 |     const released = waitForPortReleased(CDP_PORT, 5000);
 517 |     if (!released) {
 518 |       return {
 519 |         ok: false,
 520 |         replaced: true,
 521 |         error: `Headless managed Chrome on port ${CDP_PORT} was terminated, but the port did not release in time.`,
 522 |       };
 523 |     }
 524 |     console.log(`[Launcher] Replaced headless managed Chrome on :${CDP_PORT} (PID: ${headlessManaged}) with a visible browser launch.`);
 525 |     return { ok: false, replaced: true, error: 'Headless managed Chrome was terminated and will be relaunched visibly.' };
 526 |   } catch (error) {
 527 |     return {
 528 |       ok: false,
 529 |       replaced: false,
 530 |       error: `Headless managed Chrome on port ${CDP_PORT} could not be terminated: ${error.message}`,
 531 |     };
 532 |   }
 533 | }
