 536 |   resetShutdownReceipt();
 537 |   const existing = await findExistingRuntime();
 538 |   if (existing.ok) {
 539 |     console.log(`[Launcher] Existing runtime already active at ${existing.url}`);
 540 |     console.log(`[Launcher] Reusing ports: agent=${existing.agentPort}, relay=${existing.relayPort || 'unknown'}`);
 541 |     return;
 542 |   }
 543 | 
 544 |   const relayPort = await portManager.acquirePort(getRelayPort(PROJECT_CONFIG), 'relay', false);
 545 |   boundRelayPort = relayPort.port;
 546 |   portManager.recordBoundPort(boundRelayPort, 'relay');
 547 | 
 548 |   relayServer = new RelayServer({
 549 |     port: boundRelayPort,
 550 |     sessionToken: persistedRelayToken || undefined,
