 22 | function sleep(ms, signal) {
 23 |   return new Promise((resolve, reject) => {
 24 |     if (signal?.aborted) {
 25 |       reject(abortError());
 26 |       return;
 27 |     }
 28 | 
 29 |     const onAbort = () => {
 30 |       clearTimeout(timer);
 31 |       signal?.removeEventListener('abort', onAbort);
 32 |       reject(abortError());
 33 |     };
 34 | 
 35 |     const timer = setTimeout(() => {
 36 |       signal?.removeEventListener('abort', onAbort);
 37 |       resolve();
 38 |     }, ms);
 39 | 
 40 |     signal?.addEventListener('abort', onAbort, { once: true });
 41 |   });
 42 | }
