 50 | /**
 51 |  * Wait for the local agent without imposing an elapsed-time deadline.
 52 |  * Cancellation remains deterministic through the loop-owned AbortSignal.
 53 |  */
 54 | function waitForAgentResult(promise, signal) {
 55 |   return new Promise((resolve, reject) => {
 56 |     if (signal?.aborted) {
 57 |       reject(abortError());
 58 |       return;
 59 |     }
 60 | 
 61 |     let settled = false;
 62 | 
 63 |     const finish = (fn, value) => {
 64 |       if (settled) return;
 65 |       settled = true;
 66 |       signal?.removeEventListener('abort', onAbort);
 67 |       fn(value);
 68 |     };
 69 | 
 70 |     const onAbort = () => finish(reject, abortError());
 71 | 
 72 |     signal?.addEventListener('abort', onAbort, { once: true });
 73 | 
 74 |     Promise.resolve(promise).then(
 75 |       value => finish(resolve, value),
 76 |       error => finish(reject, error),
 77 |     );
 78 |   });
 79 | }
