 266 | async function waitForCdpReady(port, timeoutMs) {
 267 |   const deadline = Date.now() + Math.max(0, Number(timeoutMs) || 0);
 268 |   let lastError = '';
 269 |   while (Date.now() < deadline) {
 270 |     const listening = await isPortInUse(Number(port));
 271 |     if (!listening) {
 272 |       await delay(250);
 273 |       continue;
 274 |     }
 275 |     try {
 276 |       const url = `http://127.0.0.1:${port}/json/version`;
 277 |       const response = await getJson(url, 2000);
 278 |       if (response && typeof response === 'object' && response.webSocketDebuggerUrl) {
 279 |         return { ok: true, browser: String(response.Browser || ''), webSocketDebuggerUrl: String(response.webSocketDebuggerUrl || '') };
 280 |       }
 281 |       lastError = 'CDP /json/version returned no webSocketDebuggerUrl';
 282 |     } catch (err) {
 283 |       lastError = err?.message || String(err);
 284 |     }
 285 |     await delay(250);
 286 |   }
 287 |   return { ok: false, error: `CDP port ${port} not ready within ${Math.max(0, Number(timeoutMs) || 0)}ms. Last error: ${lastError}` };
 288 | }
