 295 | function cleanOrphanChromeProcesses() {
 296 |   if (process.platform !== 'win32') return { ok: true };
 297 |   const profile = String(CHROME_USER_DATA || '').toLowerCase().replace(/\//g, '\\');
 298 |   if (!profile) return { ok: true };
 299 | 
 300 |   const orphans = [];
 301 |   try {
 302 |     const output = String(require('node:child_process').execSync(
 303 |       `wmic process where "name='chrome.exe'" get ProcessId,CommandLine /format:csv`,
 304 |       { encoding: 'utf8', windowsHide: true, timeout: 5000, stdio: ['ignore', 'pipe', 'ignore'] }
 305 |     ) || '');
 306 |     for (const line of output.split(/\r?\n/)) {
 307 |       if (!line.includes('chrome.exe')) continue;
 308 |       if (line.includes('wmic.exe')) continue;
 309 |       const pidMatch = line.match(/(\d+)\s*$/);
 310 |       const cmd = String(line || '').toLowerCase();
 311 |       if (!cmd.includes(profile)) continue;
 312 |       if (cmd.includes(`--remote-debugging-port=${String(CDP_PORT).toLowerCase()}`)) continue;
 313 |       if (cmd.includes('type=')) continue;
 314 |       const pid = Number(pidMatch?.[1]);
 315 |       if (pid > 0) orphans.push(pid);
 316 |     }
 317 |   } catch { /* wmic may fail - fall through */ }
 318 | 
 319 |   for (const pid of orphans) {
 320 |     try { process.kill(pid, 'SIGTERM'); } catch { /* already dead */ }
 321 |   }
 322 |   if (orphans.length) {
 323 |     const deadline = Date.now() + 3000;
 324 |     while (Date.now() < deadline) {
 325 |       const stillAlive = orphans.some(pid => {
 326 |         try { process.kill(pid, 0); return true; } catch { return false; }
 327 |       });
 328 |       if (!stillAlive) break;
 329 |       require('node:child_process').execSync(`taskkill /F /PID ${pid} 2>nul`, { windowsHide: true, stdio: 'ignore' });
 330 |     }
 331 |   }
 332 | 
 333 |   // Clean stale Singleton lock files from the managed profile directory
 334 |   const lockFiles = [
 335 |     path.join(CHROME_USER_DATA, 'SingletonLock'),
 336 |     path.join(CHROME_USER_DATA, 'SingletonSocket'),
 337 |     path.join(CHROME_USER_DATA, 'SingletonCookie'),
 338 |     path.join(CHROME_USER_DATA, 'Default', 'Network', 'lock'),
 339 |   ];
 340 |   for (const file of lockFiles) {
 341 |     try { fs.rmSync(file, { force: true }); } catch { /* ignore */ }
 342 |   }
 343 | 
 344 |   return { ok: true, cleaned: orphans.length };
 345 | }
