 495 | function ensureReusableChromeForProvider() {
 496 |   if (process.platform !== 'win32') {
 497 |     return { ok: true };
 498 |   }
 499 | 
 500 |   const listeners = findListeningProcessIdsForPort(CDP_PORT);
 501 |   if (!listeners.length) {
 502 |     return { ok: false, error: `CDP port ${CDP_PORT} is marked in use but no listening process could be resolved.` };
 503 |   }
 504 | 
 505 |   const headlessManaged = listeners.find(pid => {
 506 |     const commandLine = readWindowsProcessCommandLine(pid);
 507 |     return isHeadlessManagedChromeCommandLine(commandLine);
