 514 |   try {
 515 |     execSync(`taskkill /pid ${headlessManaged} /t /f`, { stdio: 'ignore', windowsHide: true, timeout: 5000 });
 516 |     const released = waitForPortReleased(CDP_PORT, 5000);
 517 |     if (!released) {
