 519 |         ok: false,
 520 |         replaced: true,
 521 |         error: `Headless managed Chrome on port ${CDP_PORT} was terminated, but the port did not release in time.`,
 522 |       };
 523 |     }
 524 |     console.log(`[Launcher] Replaced headless managed Chrome on :${CDP_PORT} (PID: ${headlessManaged}) with a visible browser launch.`);
 525 |     return { ok: false, replaced: true, error: 'Headless managed Chrome was terminated and will be relaunched visibly.' };
 526 |   } catch (error) {
 527 |     return {
 528 |       ok: false,
 529 |       replaced: false,
 530 |       error: `Headless managed Chrome on port ${CDP_PORT} could not be terminated: ${error.message}`,
 531 |     };
 532 |   }
